const i = $json ?? {};
const clean = v => (v === undefined || v === null) ? null : (String(v).trim() || null);

const appointmentId = clean(i.appointment_id);
const startAtRaw = clean(i.start_at);
const base = (clean(i.booking_base_url) || '').replace(/\/$/, '');

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!base) throw new Error('booking_base_url no configurado (nodo Config)');
if (!appointmentId || !uuid.test(appointmentId)) throw new Error('appointment_id no es un UUID válido');
if (!startAtRaw) throw new Error('start_at es obligatorio');
if (Number.isNaN(new Date(startAtRaw).getTime())) throw new Error(`start_at no es una fecha válida: ${startAtRaw}`);

// end_at se ignora: el Booking API lo recalcula desde la duración del servicio.
return [{ json: {
  _url: base + '/api/reschedule',
  _body: { appointment_id: appointmentId, new_start_at: startAtRaw },
} }];

const r = $json ?? {};
const status = r.statusCode ?? 0;
const body = (r.body ?? r) || {};

if (body.ok === true) {
  return [{ json: {
    status: 'rescheduled',
    appointment: {
      id: body.appointment_id,
      start_at: body.start_at,
      end_at: body.end_at,
      status: body.status,
      primary_resource_id: body.primary_resource_id,
    },
  } }];
}

return [{ json: {
  status: 'error',
  error: body.error || ('http_' + status),
  message: body.detail || 'El Booking API rechazó la reprogramación',
} }];
